selector_to_html = {"a[href=\"#neural-network-pooling\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Neural Network \u2014 Pooling<a class=\"headerlink\" href=\"#neural-network-pooling\" title=\"Link to this heading\">#</a></h3><p>max_pool1d, max_pool2d, max_pool3d, avg_pool1d, avg_pool2d, avg_pool3d, adaptive_avg_pool1d, adaptive_avg_pool2d, adaptive_avg_pool3d, adaptive_max_pool1d, adaptive_max_pool2d, adaptive_max_pool3d</p>", "a[href=\"#linear-algebra\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Linear Algebra<a class=\"headerlink\" href=\"#linear-algebra\" title=\"Link to this heading\">#</a></h3><p>mv, mm, matmul, dot</p>", "a[href=\"#operator-list\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Operator List<a class=\"headerlink\" href=\"#operator-list\" title=\"Link to this heading\">#</a></h2><p>The complete operator registry is maintained at <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagDNN/tree/master/conf\">FlagDNN conf/operators.yaml</a>.</p>", "a[href=\"#math-logical\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Math \u2014 Logical<a class=\"headerlink\" href=\"#math-logical\" title=\"Link to this heading\">#</a></h3><p>logical_and, logical_or, logical_not</p>", "a[href=\"#math-binary\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Math \u2014 Binary<a class=\"headerlink\" href=\"#math-binary\" title=\"Link to this heading\">#</a></h3><p>add, sub, mul, div, pow, mod, max, min, scale, eq, ne, lt, le, gt, ge, minimum, maximum, fmin, fmax</p>", "a[href=\"#flagdnn-user-guide\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagDNN User Guide<a class=\"headerlink\" href=\"#flagdnn-user-guide\" title=\"Link to this heading\">#</a></h1><h2>Use FlagDNN<a class=\"headerlink\" href=\"#use-flagdnn\" title=\"Link to this heading\">#</a></h2><p>FlagDNN integrates directly with PyTorch. Import the package and call operators on CUDA tensors:</p>", "a[href=\"#neural-network-activation\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Neural Network \u2014 Activation<a class=\"headerlink\" href=\"#neural-network-activation\" title=\"Link to this heading\">#</a></h3><p>relu, gelu, gelu_approx_tanh, silu, swish, leaky_relu, leaky_relu_, prelu, elu, elu_, rrelu, rrelu_, mish, softplus, softsign, softshrink, hardswish, relu6, selu, glu, celu, tanh, sigmoid, sigmoid_backward, logsigmoid, hardtanh, hardtanh_, threshold, threshold_</p>", "a[href=\"#neural-network-convolution\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Neural Network \u2014 Convolution<a class=\"headerlink\" href=\"#neural-network-convolution\" title=\"Link to this heading\">#</a></h3><p>conv1d, conv2d, conv3d, conv_fprop, conv_dgrad, conv_wgrad, causal_conv1d</p>", "a[href=\"#neural-network-other\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Neural Network \u2014 Other<a class=\"headerlink\" href=\"#neural-network-other\" title=\"Link to this heading\">#</a></h3><p>interpolate</p>", "a[href=\"#math-bitwise\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Math \u2014 Bitwise<a class=\"headerlink\" href=\"#math-bitwise\" title=\"Link to this heading\">#</a></h3><p>bitwise_and, bitwise_or, bitwise_xor</p>", "a[href=\"#fused\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Fused<a class=\"headerlink\" href=\"#fused\" title=\"Link to this heading\">#</a></h3><p>add_square, rmsnorm_rht_amax</p>", "a[href=\"#neural-network-normalization\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Neural Network \u2014 Normalization<a class=\"headerlink\" href=\"#neural-network-normalization\" title=\"Link to this heading\">#</a></h3><p>batch_norm, batchnorm, batchnorm_inference, layernorm, layer_norm, rms_norm, rmsnorm, group_norm</p>", "a[href=\"#neural-network-softmax\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Neural Network \u2014 Softmax<a class=\"headerlink\" href=\"#neural-network-softmax\" title=\"Link to this heading\">#</a></h3><p>softmax, softmin, log_softmax</p>", "a[href=\"#neural-network-attention\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Neural Network \u2014 Attention<a class=\"headerlink\" href=\"#neural-network-attention\" title=\"Link to this heading\">#</a></h3><p>sdpa, sdpa_backward</p>", "a[href=\"#math-comparison\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Math \u2014 Comparison<a class=\"headerlink\" href=\"#math-comparison\" title=\"Link to this heading\">#</a></h3><p>cmp_eq, cmp_neq, cmp_lt, cmp_le, cmp_gt, cmp_ge</p>", "a[href=\"#loss\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Loss<a class=\"headerlink\" href=\"#loss\" title=\"Link to this heading\">#</a></h3><p>kl_div, mse_loss, l1_loss</p>", "a[href=\"#tensor-operations\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Tensor Operations<a class=\"headerlink\" href=\"#tensor-operations\" title=\"Link to this heading\">#</a></h3><p>identity, reshape, transpose, slice, concatenate, gen_index, binary_select, one_hot, embedding</p>", "a[href=\"#use-flagdnn\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Use FlagDNN<a class=\"headerlink\" href=\"#use-flagdnn\" title=\"Link to this heading\">#</a></h2><p>FlagDNN integrates directly with PyTorch. Import the package and call operators on CUDA tensors:</p>", "a[href=\"#math-unary\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Math \u2014 Unary<a class=\"headerlink\" href=\"#math-unary\" title=\"Link to this heading\">#</a></h3><p>sqrt, abs, neg, clamp, isinf, isnan, square, rsqrt, positive, log, exp, bitwise_not, ceil, floor, reciprocal, sin, cos, tan, erf</p>", "a[href=\"#reduction\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Reduction<a class=\"headerlink\" href=\"#reduction\" title=\"Link to this heading\">#</a></h3><p>sum, mean, prod, reduction, cumsum, cumprod, cummin, cummax, any, all</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
